\coordinate (D) at (6,0);
\coordinate (E) at (2,2);
\coordinate (F) at (4,1);
\draw (A)--(E) node[midway,above right] {$4$};
\draw (C)--(E) node[midway,above left] {$7$};
\draw (E)--(F) node[midway,above right] {$7$};
\draw (F)--(B) node[midway,above left] {$6$};
\draw (B)--(D) node[midway,right] {$6$};
\foreach \v/\p in {A/above left,B/above right,C/below left,D/below right,E/above,F/below}{\fill[black] (\v) circle (2pt);\path (\v) node[\p] {$\v$};}
\end{tikzpicture}
[/tikz]

